// 添付指示書による既存カード・裁定の更新
(function () {
  const items = window.RULINGS || (window.RULINGS = []);
  const norm = (value) => String(value || "").normalize("NFKC").toLowerCase().replace(/[^a-z0-9\u3040-\u30ff\u3400-\u9fff]/gi, "");
  const card = (name) => items.find((item) => norm(item.name) === norm(name))
    || items.find((item) => norm(item.name).includes(norm(name)) || norm(name).includes(norm(item.name)));
  const qaById = (id) => {
    const wanted = norm(id).replace(/^r/, "");
    for (const item of items) for (const entry of item.qa || []) {
      if (norm(entry.managementId).replace(/^r/, "") === wanted) return { item, entry };
    }
    return null;
  };
  const replaceOverview = (name, overview) => { const item = card(name); if (item) item.overview = overview; };
  const appendQa = (name, entry) => {
    const item = card(name); if (!item) return;
    item.qa ||= [];
    const found = item.qa.find((qa) => norm(qa.question) === norm(entry.question));
    if (found) Object.assign(found, entry); else item.qa.push(entry);
  };
  const setQa = (id, question, answer) => {
    const match = qaById(id);
    if (match) { if (question) match.entry.question = question; match.entry.answer = answer; }
  };

  replaceOverview("アーカナイト・マジシャン", "▶誘発効果は強制\n▶チェーン２で《フォーミュラ・シンクロン》の効果によりシンクロ召喚に成功したときもタイミングを逃さず発動する");
  appendQa("アームズ・エイド", {
    question: "このカードの装備中に《トラゴエディア》等の攻撃力が？のモンスターを戦闘破壊した場合のダメージはどうなりますか？",
    answer: "０です。"
  });
  setQa("R-GN439Z7B66", "", "まず装備先のモンスターの攻撃力は800下がります。このカードの装備状態は維持され、装備を解除して特殊召喚する効果も発動できます。ダメージを与える効果も適用されますが、装備魔法として付与する攻撃力1000アップだけはエンドフェイズまで適用されなくなります。");
  setQa("R-V6XU4VHLEK", "", "発動できます。ただし、デッキからのサーチは不可で、墓地からのみ回収できます。\nこのカードの発動にチェーン《リビングデッドの呼び声》で《ライオウ》が出た場合も同様です。※発動時に対象は選ばず、効果処理時に選びます。");

  const aojOverview = "▶２番目と３番目の効果の「手札を墓地へ送る」行為はコスト\n※《マクロコスモス》などの適用下では１番目の効果しか発動できない。\n※《次元の裂け目》の適用下では魔法・罠のみをコスト墓地に送ることが可能であれば発動可能。\n\n▶３番目の効果の効果処理時に除外される状況となった場合、ハンデスは可能だが、ダメージを与える事はできない。";
  const aoj = card("Ａ・Ｏ・Ｊ ディサイシブ・アームズ") || card("ＡＯＪディサイシブ・アームズ");
  if (aoj) aoj.overview = [aoj.overview, aojOverview].filter(Boolean).join("\n\n");
  appendQa("Ａ・Ｏ・Ｊ ディサイシブ・アームズ", {
    question: "自分が使用した３番目の効果にチェーンして《マクロコスモス》を発動されました。どうなりますか？",
    answer: "効果処理時にハンデスした相手の手札が除外される状況となった場合、そのまま除外は行いますが、墓地に送れていないため、ダメージは発生しません。"
  });

  replaceOverview("Ａ・ジェネクス・バードマン", "▶手札で発動できる起動効果\n▶処理時に、『このカードを手札から特殊召喚する』処理を行う。\n▶この効果で特殊召喚したこのカードは、ただちに『フィールドから離れた場合に除外される』状態となる。\n▶この効果を発動するために風属性モンスターを手札に戻した場合、ただちに『このカードの攻撃力は５００アップする』効果が適用される。\n▶《エフェクトヴェーラー》《禁じられた聖杯》《スキルドレイン》等で効果無効状態のとき、500の打点アップ効果は無効となる。");
  setQa("R-VB8KUCCGYX", "《エレキタリス》や《冥界の魔王 ハ・デス》に戦闘破壊された場合、墓地から特殊召喚できますか？", "これらの効果が誘発・適用された後で墓地に送られた場合、召喚ルール効果の発動はできません。効果全体が無効にされるためです。");
  const difficult = qaById("R-78WVQCYMP7");
  if (difficult) {
    difficult.entry.difficult = true;
    difficult.item.specialTags = [...new Set([...(difficult.item.specialTags || []), "難解"])];
  }
  replaceOverview("異次元からの帰還", "▶発動する際に、コストとしてライフポイントを半分払います。\n▶対象を取る効果ではありません。効果処理の際に、除外されている自分のモンスターを可能な限り選んで特殊召喚します。\n▶除外されている自分のモンスターが1体もない場合や、特殊召喚できないモンスターのみが除外されているような場合には発動する事自体できません。\n▶『この効果で特殊召喚したモンスターはエンドフェイズ時にゲームから除外される』処理はチェーンブロックを作らない残存効果。\n▶この効果によって特殊召喚されたモンスターが《禁じられた聖槍》等の効果で罠カードの効果を受けなくなった場合でも、『この効果で特殊召喚したモンスターはエンドフェイズ時にゲームから除外される』とした残存効果は既に適用されていますので、エンドフェイズの処理は通常通り適用され、除外されます。\n※類似裁定《Ｗ星雲隕石》の残存効果");
  appendQa("異次元の女戦士", {
    question: "自分の場に１体だけのこのカードでリバースモンスターを攻撃しました。仮にそのモンスターが《スノーマン・イーター》であり、自分はそれを除外したい。相手は《スノーマンイーター》の効果でこのカードを対象に破壊したい場合、どのような処理となりますか？",
    answer: "このカードとリバース効果モンスターは、ダメージステップ表⑤戦闘結果解決時の同一タイミングに処理を行います。リバース効果は強制のためチェーン１、任意で発動できるこのカードがチェーン２として処理します。逆順処理の結果として、チェーン２のこのカードの効果でこのカード自身と相手の《スノーマン・イーター》を除外し、チェーン１で相手の《スノーマン・イーター》の効果が誘発しますが、自分の場には既に効果対象となったこのカードは存在しないので、誘発はするも不発となった扱いとなります。\n※この場合でも、《スノーマン・イーター》等のリバース効果は、あくまでフィールド上で発動した扱い。\n※仮に《異次元の女戦士》側のフィールドに他のモンスターが存在した場合、TPが先に《異次元の女戦士》の効果を発動するか決定し、その後NTPがリバース効果の発動時の対象を選択し発動、それぞれチェーンを組む形となる。\n※よくある質問《ライトロードハンター・ライコウ》でも同様の処理。",
    pinFirst: true
  });

  replaceOverview("イビリチュア・メロウガイスト", "【効果の基本】\n▶誘発効果\n▶対象を取らない効果\n▶表④ダメージ計算後に発動し、残存効果は表⑥ダメージステップ終了時に適用\n▶効果の発動と、デッキへ戻す処理の適用タイミングが分かれている\n－区切り線－\n【戦闘相手ごとの処理】\n▶相打ち：発動できない\n▶リバース効果：リバース効果を発動し、その処理後にデッキへ戻す\n▶《異次元の女戦士》《Ｄ.Ｄ.アサイラント》：このカードが発動してもお互い除外\n▶《スクリーチ》《エレキトンボ》《エア・サーキュレーター》《ＴＧ ワンダー・マジシャン》：デッキ（エクストラデッキ）へ戻した場合は発動しない\n※戦闘破壊確定≠破壊であり、破壊自体を置換しているため。詳しくはＱ＆Ａを参照してください。\n▶《Ｅ・ＨＥＲＯ アブソルートＺｅｒｏ》：誘発するトリガーが破壊ではなく、『フィールドを離れた時』のため、エクストラデッキへ戻しても発動する\n▶《大天使クリスティア》：このカードはそもそも発動できず、ダメージステップ終了時に《大天使クリスティア》はＣＢ作らず即デッキの一番上へ戻る\n▶自己蘇生後の《ゾンビキャリア》《ボルト・ヘッジホッグ》：そもそも発動できない\n▶宝玉獣：デッキへ戻した場合は魔法・罠ゾーンに移動する効果は発動しない\n▶《エレキタリス》：《エレキタリス》がデッキへ戻り、以後このカードの効果は無効\n▶《ゼンマイジャグラー》：このカードは破壊され、《ゼンマイジャグラー》はデッキへ戻る");
  appendQa("イビリチュア・メロウガイスト", {
    question: "このカードが《メタモルポット》に攻撃し、ダメージステップ表④にてデッキバウンス効果を発動しました。その後、ダメステ表⑤のタイミングで《メタモルポッド》の効果で《暗黒界の龍神グラファ》が捨てられました。⑤の追加誘発解決タイミングにおいて、その破壊効果でこのカードが破壊されました。⑥ダメージステップ終了時に、このカードの残存効果は発動し、《メタモルポッド》をデッキバウンスできますか？",
    answer: "はい、可能です。ダメステ表④で発動に成功した場合、その後のこのカードの所在に関係なく、⑥ダメージステップ終了時に残存効果としてデッキバウンス処理がチェーンブロックを作らず処理されます。"
  });
  replaceOverview("インフェルニティ・デーモン", "■２つの誘発効果を有するカード\n①手札が0枚の状態でドローした場合に自身を特殊召喚できる誘発効果\n②手札が0枚の状態で特殊召喚に成功した時に《インフェルニティ》カード1枚を手札に加えられる誘発効果\n\n■②の効果はタイミングを逃す可能性があるため要注意\nＡ：《ZERO－MAX》での特殊召喚成功時\nＢ：《リビングデッドの呼び声》《デーモンの雄叫び》によるチェーン２以降の特殊召喚時");
  replaceOverview("インフェルニティ・ネクロマンサー", "■召喚成功時に誘発効果により守備表示となる\n\n■手札0枚で効果を得るのは永続効果\n▷手札がある場合は、そもそも起動効果を発動宣言不可。\n▷《スキルドレイン》適用中は手札が何枚であっても、起動効果の発動宣言不可。\n\n■手札が０枚であるとき、起動効果による蘇生を行える。");
  const necro = card("インフェルニティ・ネクロマンサー");
  if (necro) necro.qa = [];

  // 効果分類だけを尋ねるQ&Aは概要に移し、重複表示を避ける。
  for (const item of items) {
    const kept = [];
    for (const entry of item.qa || []) {
      const question = String(entry.question || "");
      if (/効果.*(?:分類|種類|種別)|(?:分類|種類|種別).*効果|どのような効果(?:に分類|ですか)/.test(question) && /効果/.test(question)) {
        const answer = String(entry.answer || "").trim().replace(/[。．.!！?？]+$/, "");
        if (answer) item.overview = `▶効果分類：${answer}${item.overview ? `\n${item.overview}` : ""}`;
      } else kept.push(entry);
    }
    item.qa = kept;
  }
})();
